import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p47_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor sum_reduce_dim1_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("sum_reduce_dim1", &sum_reduce_dim1_cuda, "sum reduction over dim=1 (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Kernel: each thread handles one k index, loops over j=0..J-1 accumulating sum.
// Grid: (ceil(K/256), N), Block: (256,)
__global__ void sum_reduce_dim1_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int J, int K
) {
    int k = blockIdx.x * blockDim.x + threadIdx.x;
    int n = blockIdx.y;
    if (k >= K || n >= N) return;

    const float* row = input + (long long)n * J * K + k;
    float acc = 0.0f;
    for (int j = 0; j < J; ++j) {
        acc += row[(long long)j * K];
    }
    output[(long long)n * K + k] = acc;
}

torch::Tensor sum_reduce_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() == 3, "Input must be rank-3");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    int N = x.size(0);
    int J = x.size(1);
    int K = x.size(2);

    // Output shape: [N, 1, K]
    auto output_flat = torch::empty({N, K}, x.options());

    const int BLOCK = 256;
    dim3 grid((K + BLOCK - 1) / BLOCK, N);
    dim3 block(BLOCK);

    sum_reduce_dim1_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        output_flat.data_ptr<float>(),
        N, J, K
    );

    return output_flat.view({N, 1, K});
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs sum reduction over a specified dimension.
        """
    def __init__(self, dim: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the model with the dimension to reduce over.

                Args:
                    dim (int): Dimension to reduce over.
                """
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies sum reduction over the specified dimension.

                Args:
                    x (torch.Tensor): Input tensor of shape (..., dim, ...).

                Returns:
                    torch.Tensor: Output tensor after sum reduction, shape (..., 1, ...).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (x.is_cuda and self.dim == 1 and x.dtype == torch.float32
                and x.dim() == 3 and x.is_contiguous()):
            return _stark_get_extension().sum_reduce_dim1(x)
        return torch.sum(x, dim=self.dim, keepdim=True)
        # <<<END_IMPROVE>>>

